import React from 'react';
import {
  Alert,
  Card,
  CardContent,
  Chip,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';

type GasEntry = {
  gas?: string;
  scope?: string;
  massKg?: number;
  co2eTons?: number;
};

type ExportComplianceDepthPanelProps = {
  gasByGasInventory?: {
    gases?: GasEntry[];
    totalCo2eTons?: number;
    methodology?: string;
    measured?: boolean;
  };
  managementSystems?: {
    iso27001?: { standard?: string; readinessScore?: number; items?: Array<{ id?: string; title?: string; status?: string }> };
    iso9001?: { standard?: string; readinessScore?: number; items?: Array<{ id?: string; title?: string; status?: string }> };
  };
};

const ExportComplianceDepthPanel: React.FC<ExportComplianceDepthPanelProps> = ({
  gasByGasInventory,
  managementSystems,
}) => (
  <Stack spacing={2}>
    <Typography variant="h6">Advanced disclosure depth</Typography>

    <Card variant="outlined">
      <CardContent>
        <Typography variant="subtitle1" gutterBottom>Gas-by-gas inventory</Typography>
        {gasByGasInventory?.methodology ? (
          <Alert severity={gasByGasInventory.measured ? 'success' : 'info'} sx={{ mb: 1 }}>
            {gasByGasInventory.methodology}
          </Alert>
        ) : null}
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
          Total CO2e: {gasByGasInventory?.totalCo2eTons?.toLocaleString() ?? '—'} t
        </Typography>
        <List dense>
          {(gasByGasInventory?.gases || []).map((entry) => (
            <ListItem key={`${entry.gas}-${entry.scope}`} disableGutters>
              <ListItemText
                primary={`${entry.gas} (${entry.scope})`}
                secondary={`${entry.massKg?.toLocaleString() ?? '—'} kg · ${entry.co2eTons?.toFixed(3) ?? '—'} tCO2e`}
              />
            </ListItem>
          ))}
        </List>
      </CardContent>
    </Card>

    {(['iso27001', 'iso9001'] as const).map((key) => {
      const snapshot = managementSystems?.[key];
      if (!snapshot) return null;
      return (
        <Card key={key} variant="outlined">
          <CardContent>
            <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
              <Typography variant="subtitle1">{snapshot.standard || key.toUpperCase()}</Typography>
              <Chip size="small" label={`${snapshot.readinessScore ?? 0}%`} />
            </Stack>
            <List dense>
              {(snapshot.items || []).map((item) => (
                <ListItem key={item.id} disableGutters>
                  <ListItemText primary={`${item.id} — ${item.title}`} />
                  <Chip
                    size="small"
                    label={item.status === 'implemented' ? 'Implemented' : 'Gap'}
                    color={item.status === 'implemented' ? 'success' : 'default'}
                    variant="outlined"
                  />
                </ListItem>
              ))}
            </List>
          </CardContent>
        </Card>
      );
    })}
  </Stack>
);

export default ExportComplianceDepthPanel;
