import React from 'react';
import {
  Alert,
  Box,
  Card,
  CardContent,
  Chip,
  LinearProgress,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';

type GapItem = {
  id?: string;
  title?: string;
  description?: string;
  status?: string;
  value?: unknown;
};

type FrameworkGap = {
  framework?: string;
  overallReadinessScore?: number;
  submissionReady?: boolean;
  items?: GapItem[];
  blockers?: string[];
};

type ExportGapClosurePanelProps = {
  exportGapClosure?: Record<string, FrameworkGap> | null;
};

const frameworkLabel = (key: string): string => {
  const labels: Record<string, string> = {
    cdp: 'CDP Climate',
    csrd: 'CSRD / ESRS',
    gri: 'GRI 305',
    tcfd: 'TCFD / ISSB',
    ecovadis: 'EcoVadis',
    eudr: 'EUDR',
  };
  return labels[key] || key.toUpperCase();
};

const ExportGapClosurePanel: React.FC<ExportGapClosurePanelProps> = ({ exportGapClosure }) => {
  const sections = Object.entries(exportGapClosure || {});

  if (sections.length === 0) {
    return <Alert severity="info">Export gap-closure checklists load with the export track.</Alert>;
  }

  return (
    <Stack spacing={2}>
      <Typography variant="h6">Export framework gap closure</Typography>
      {sections.map(([key, section]) => (
        <Card key={key} variant="outlined">
          <CardContent>
            <Stack direction="row" alignItems="center" spacing={2} sx={{ mb: 1 }}>
              <Typography variant="subtitle1">{frameworkLabel(key)}</Typography>
              <Chip
                size="small"
                label={section.submissionReady ? 'Submission ready' : 'Gaps open'}
                color={section.submissionReady ? 'success' : 'warning'}
              />
              <Box sx={{ flex: 1 }}>
                <LinearProgress
                  variant="determinate"
                  value={Math.min(100, section.overallReadinessScore ?? 0)}
                  sx={{ height: 6, borderRadius: 1 }}
                />
              </Box>
              <Typography variant="body2" color="text.secondary">
                {section.overallReadinessScore ?? 0}%
              </Typography>
            </Stack>
            {(section.blockers || []).slice(0, 3).map((blocker) => (
              <Alert key={blocker} severity="warning" sx={{ mb: 1 }}>
                {blocker}
              </Alert>
            ))}
            <List dense disablePadding>
              {(section.items || []).map((item) => (
                <ListItem key={item.id || item.title} disableGutters>
                  <ListItemText
                    primary={item.title}
                    secondary={item.description}
                  />
                  <Chip
                    size="small"
                    label={item.status === 'complete' ? 'Complete' : 'Gap'}
                    color={item.status === 'complete' ? 'success' : 'default'}
                    variant="outlined"
                  />
                </ListItem>
              ))}
            </List>
          </CardContent>
        </Card>
      ))}
    </Stack>
  );
};

export default ExportGapClosurePanel;
