import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

type ConfirmationItem = {
  confirmKey?: string;
  label?: string;
  value?: unknown;
  inferred?: boolean;
  confirmed?: boolean;
  status?: string;
};

type FrameworkConfirmation = {
  framework?: string;
  items?: ConfirmationItem[];
  pendingCount?: number;
  blockers?: string[];
};

type InferredFieldConfirmationPanelProps = {
  period?: string;
  /** When false (default), wait for user click before fetching. */
  eager?: boolean;
};

const InferredFieldConfirmationPanel: React.FC<InferredFieldConfirmationPanelProps> = ({
  period = 'annual',
  eager = false,
}) => {
  const [expanded, setExpanded] = useState(eager);
  const [loading, setLoading] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [confirmations, setConfirmations] = useState<Record<string, FrameworkConfirmation>>({});
  const [busyKey, setBusyKey] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getInferredFieldConfirmations({ period });
      setConfirmations((res as { data?: Record<string, FrameworkConfirmation> })?.data || {});
      setLoaded(true);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load inferred field confirmations');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    if (eager && !loaded) {
      void load();
    }
  }, [eager, loaded, load]);

  const confirmField = async (confirmKey: string) => {
    setBusyKey(confirmKey);
    try {
      await ApiService.confirmInferredField({ confirmKey, confirmed: true });
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to confirm field');
    } finally {
      setBusyKey(null);
    }
  };

  if (!expanded) {
    return (
      <Card variant="outlined">
        <CardContent>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }} justifyContent="space-between">
            <Box>
              <Typography variant="subtitle1">Inferred field confirmation</Typography>
              <Typography variant="body2" color="text.secondary">
                Confirm TCFD, GRI, and CSRD fields inferred from inventory before buyer upload.
              </Typography>
            </Box>
            <Button
              variant="outlined"
              onClick={() => {
                setExpanded(true);
                if (!loaded) {
                  void load();
                }
              }}
            >
              Review fields
            </Button>
          </Stack>
        </CardContent>
      </Card>
    );
  }

  if (loading && !loaded) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  const entries = Object.entries(confirmations);
  if (entries.length === 0) {
    return (
      <Alert severity="info">
        No inferred fields awaiting confirmation for this period.
      </Alert>
    );
  }

  return (
    <Stack spacing={2}>
      <Typography variant="h6">Inferred field confirmation</Typography>
      <Typography variant="body2" color="text.secondary">
        Confirm TCFD, GRI, and CSRD fields that were inferred from inventory before buyer portal upload.
      </Typography>
      {error ? <Alert severity="error">{error}</Alert> : null}
      {entries.map(([framework, section]) => (
        <Card key={framework} variant="outlined">
          <CardContent>
            <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
              <Typography variant="subtitle1">{framework.toUpperCase()}</Typography>
              {(section.pendingCount ?? 0) > 0 ? (
                <Chip size="small" color="warning" label={`${section.pendingCount} pending`} />
              ) : (
                <Chip size="small" color="success" label="All confirmed" />
              )}
            </Stack>
            <List dense>
              {(section.items || []).map((item) => (
                <ListItem
                  key={item.confirmKey || item.label}
                  secondaryAction={
                    item.status === 'pending_confirmation' ? (
                      <Button
                        size="small"
                        variant="outlined"
                        disabled={busyKey === item.confirmKey}
                        onClick={() => item.confirmKey && void confirmField(item.confirmKey)}
                      >
                        Confirm
                      </Button>
                    ) : null
                  }
                >
                  <ListItemText
                    primary={item.label}
                    secondary={
                      item.status === 'missing'
                        ? 'Missing — complete pack first'
                        : item.inferred
                          ? `Inferred value: ${String(item.value).slice(0, 80)}`
                          : String(item.value ?? '')
                    }
                  />
                  <Chip
                    size="small"
                    label={item.status?.replace(/_/g, ' ') || 'unknown'}
                    color={item.status === 'confirmed' ? 'success' : 'default'}
                    variant="outlined"
                    sx={{ ml: 1 }}
                  />
                </ListItem>
              ))}
            </List>
          </CardContent>
        </Card>
      ))}
    </Stack>
  );
};

export default InferredFieldConfirmationPanel;
