import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Collapse,
  Grid,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

export type QuestionSchemaItem = {
  questionId?: string;
  questionRef?: string;
  section?: string;
  responseKey: string;
  label: string;
  inputType?: 'text' | 'textarea' | 'number';
  required?: boolean;
};

export type SupplierQuestionnaireRecord = {
  id?: string | null;
  _id?: string | null;
  buyerName?: string;
  framework?: string;
  status?: string;
  questionSchema?: QuestionSchemaItem[];
  responses?: Record<string, unknown>;
};

type BuyerPackQuestionnaireWizardProps = {
  questionnaire: SupplierQuestionnaireRecord;
  period?: string;
  onSaved?: () => void;
  defaultExpanded?: boolean;
};

const getNestedValue = (source: Record<string, unknown>, path: string): unknown =>
  path.split('.').reduce<unknown>((cursor, key) => {
    if (cursor && typeof cursor === 'object' && key in (cursor as Record<string, unknown>)) {
      return (cursor as Record<string, unknown>)[key];
    }
    return undefined;
  }, source);

const setNestedValue = (
  target: Record<string, unknown>,
  path: string,
  value: unknown
): Record<string, unknown> => {
  const keys = path.split('.').filter(Boolean);
  let cursor = target;
  keys.forEach((key, index) => {
    if (index === keys.length - 1) {
      cursor[key] = value;
      return;
    }
    if (!cursor[key] || typeof cursor[key] !== 'object') {
      cursor[key] = {};
    }
    cursor = cursor[key] as Record<string, unknown>;
  });
  return target;
};

const formatFieldValue = (value: unknown, inputType?: string): string => {
  if (value == null) return '';
  if (inputType === 'number') {
    return Number.isFinite(Number(value)) ? String(value) : '';
  }
  if (typeof value === 'object') {
    return JSON.stringify(value, null, 2);
  }
  return String(value);
};

const parseFieldValue = (raw: string, inputType?: string): unknown => {
  if (inputType === 'number') {
    if (raw.trim() === '') return null;
    const numeric = Number(raw);
    return Number.isFinite(numeric) ? numeric : null;
  }
  return raw;
};

const BuyerPackQuestionnaireWizard: React.FC<BuyerPackQuestionnaireWizardProps> = ({
  questionnaire,
  period = 'annual',
  onSaved,
  defaultExpanded = false,
}) => {
  const questionnaireId = questionnaire.id || questionnaire._id || '';
  const questions = useMemo(
    () => questionnaire.questionSchema || [],
    [questionnaire.questionSchema]
  );
  const [expanded, setExpanded] = useState(defaultExpanded);
  const [responses, setResponses] = useState<Record<string, unknown>>(
    () => ({ ...(questionnaire.responses || {}) })
  );
  const [saving, setSaving] = useState(false);
  const [prefilling, setPrefilling] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  useEffect(() => {
    setResponses({ ...(questionnaire.responses || {}) });
  }, [questionnaire.responses, questionnaireId]);

  const groupedQuestions = useMemo(() => {
    const groups = new Map<string, QuestionSchemaItem[]>();
    questions.forEach((question) => {
      const section = question.section || 'General';
      const existing = groups.get(section) || [];
      existing.push(question);
      groups.set(section, existing);
    });
    return Array.from(groups.entries());
  }, [questions]);

  const handleFieldChange = useCallback((responseKey: string, rawValue: string, inputType?: string) => {
    setResponses((current) => {
      const next = { ...current };
      setNestedValue(next, responseKey, parseFieldValue(rawValue, inputType));
      return next;
    });
  }, []);

  const handleSave = async () => {
    if (!questionnaireId) return;
    setSaving(true);
    setError(null);
    setFeedback(null);
    try {
      await ApiService.updateSupplierQuestionnaire(questionnaireId, {
        responses,
        status: questionnaire.status === 'draft' ? 'responded' : questionnaire.status,
      });
      setFeedback('Questionnaire responses saved.');
      onSaved?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to save responses');
    } finally {
      setSaving(false);
    }
  };

  const handlePrefill = async (overwrite = false) => {
    if (!questionnaireId) return;
    setPrefilling(true);
    setError(null);
    setFeedback(null);
    try {
      const res = await ApiService.prefillSupplierQuestionnaireFromInventory(questionnaireId, {
        period,
        overwrite,
      });
      const payload = (res as { data?: { questionnaire?: SupplierQuestionnaireRecord; prefilledFieldCount?: number } })?.data;
      const message = (res as { message?: string })?.message;
      if (payload?.questionnaire?.responses) {
        setResponses({ ...payload.questionnaire.responses });
      }
      setFeedback(message || `Prefilled ${payload?.prefilledFieldCount ?? 0} field(s) from inventory.`);
      onSaved?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Prefill failed');
    } finally {
      setPrefilling(false);
    }
  };

  if (!questionnaireId || questions.length === 0) {
    return (
      <Alert severity="info">
        Import a buyer template to unlock the response wizard for {questionnaire.buyerName || 'this buyer'}.
      </Alert>
    );
  }

  return (
    <Box sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1, p: 2 }}>
      <Stack direction="row" justifyContent="space-between" alignItems="center" flexWrap="wrap" gap={1}>
        <Box>
          <Typography variant="subtitle2" fontWeight={700}>
            Response wizard — {questionnaire.buyerName}
          </Typography>
          <Typography variant="caption" color="text.secondary">
            {questions.length} mapped question(s) · status: {(questionnaire.status || 'draft').replace(/_/g, ' ')}
          </Typography>
        </Box>
        <Stack direction="row" spacing={1} flexWrap="wrap">
          <Button size="small" onClick={() => setExpanded((value) => !value)}>
            {expanded ? 'Hide form' : 'Fill responses'}
          </Button>
          <Button
            size="small"
            variant="outlined"
            disabled={prefilling}
            onClick={() => void handlePrefill(false)}
          >
            {prefilling ? 'Prefilling…' : 'Prefill from inventory'}
          </Button>
        </Stack>
      </Stack>

      <Collapse in={expanded}>
        <Stack spacing={2} sx={{ mt: 2 }}>
          {error ? <Alert severity="error">{error}</Alert> : null}
          {feedback ? <Alert severity="success">{feedback}</Alert> : null}

          {groupedQuestions.map(([section, sectionQuestions]) => (
            <Box key={section}>
              <Typography variant="subtitle2" gutterBottom>
                {section}
              </Typography>
              <Grid container spacing={2}>
                {sectionQuestions.map((question) => {
                  const value = getNestedValue(responses, question.responseKey);
                  const commonProps = {
                    fullWidth: true,
                    label: question.label,
                    required: Boolean(question.required),
                    value: formatFieldValue(value, question.inputType),
                    onChange: (event: React.ChangeEvent<HTMLInputElement>) =>
                      handleFieldChange(question.responseKey, event.target.value, question.inputType),
                  };

                  return (
                    <Grid item xs={12} md={question.inputType === 'textarea' ? 12 : 6} key={question.responseKey}>
                      <Stack spacing={0.5}>
                        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                          {question.questionRef ? (
                            <Chip size="small" label={question.questionRef} variant="outlined" />
                          ) : null}
                          {question.questionId ? (
                            <Typography variant="caption" color="text.secondary">
                              {question.questionId}
                            </Typography>
                          ) : null}
                        </Stack>
                        {question.inputType === 'textarea' ? (
                          <TextField {...commonProps} multiline minRows={3} />
                        ) : (
                          <TextField
                            {...commonProps}
                            type={question.inputType === 'number' ? 'number' : 'text'}
                          />
                        )}
                      </Stack>
                    </Grid>
                  );
                })}
              </Grid>
            </Box>
          ))}

          <Stack direction="row" spacing={1} flexWrap="wrap">
            <Button variant="contained" disabled={saving} onClick={() => void handleSave()}>
              {saving ? 'Saving…' : 'Save responses'}
            </Button>
            <Button variant="text" disabled={prefilling} onClick={() => void handlePrefill(true)}>
              Overwrite with latest inventory
            </Button>
          </Stack>
        </Stack>
      </Collapse>

      {prefilling ? (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1 }}>
          <CircularProgress size={16} />
          <Typography variant="caption" color="text.secondary">
            Mapping inventory pack fields…
          </Typography>
        </Box>
      ) : null}
    </Box>
  );
};

export default BuyerPackQuestionnaireWizard;
