import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

export type BuyerQuestionTemplate = {
  id: string;
  framework: string;
  label: string;
  description?: string;
  version?: string;
  questionCount?: number;
};

type BuyerQuestionnaireTemplateImportProps = {
  onImported?: () => void;
};

const BuyerQuestionnaireTemplateImport: React.FC<BuyerQuestionnaireTemplateImportProps> = ({
  onImported,
}) => {
  const [templates, setTemplates] = useState<BuyerQuestionTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [importing, setImporting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [templateId, setTemplateId] = useState('');
  const [buyerName, setBuyerName] = useState('');
  const [buyerContactEmail, setBuyerContactEmail] = useState('');
  const [dueDate, setDueDate] = useState('');

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await ApiService.listBuyerQuestionTemplates();
        const data = (res as { data?: BuyerQuestionTemplate[] })?.data || [];
        if (!cancelled) {
          setTemplates(data);
          if (data.length) {
            setTemplateId((current) => current || data[0].id);
          }
        }
      } catch (e) {
        if (!cancelled) {
          setError(e instanceof Error ? e.message : 'Failed to load buyer templates');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, []);

  const selectedTemplate = templates.find((entry) => entry.id === templateId);

  const handleImport = async () => {
    if (!templateId || !buyerName.trim()) return;
    setImporting(true);
    setError(null);
    setFeedback(null);
    try {
      const res = await ApiService.importBuyerQuestionnaireTemplate({
        templateId,
        buyerName: buyerName.trim(),
        buyerContactEmail: buyerContactEmail.trim() || undefined,
        dueDate: dueDate || undefined,
      });
      const message = (res as { message?: string })?.message
        || `Imported ${selectedTemplate?.label || 'template'} successfully.`;
      setFeedback(message);
      setBuyerName('');
      setBuyerContactEmail('');
      setDueDate('');
      onImported?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Template import failed');
    } finally {
      setImporting(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 2 }}>
        <CircularProgress size={24} />
      </Box>
    );
  }

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Import buyer template (CDP question IDs)
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Pre-load official CDP, BRSR Core, CSRD, GRI, TCFD, or EcoVadis question IDs so supplier responses map directly to buyer pack scoring.
        </Typography>
        {error ? <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert> : null}
        {feedback ? <Alert severity="success" sx={{ mb: 2 }}>{feedback}</Alert> : null}
        <Grid container spacing={2}>
          <Grid item xs={12} md={4}>
            <FormControl fullWidth>
              <InputLabel>Template</InputLabel>
              <Select
                label="Template"
                value={templateId}
                onChange={(e) => setTemplateId(String(e.target.value))}
              >
                {templates.map((template) => (
                  <MenuItem key={template.id} value={template.id}>
                    {template.label} ({template.questionCount} questions)
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Buyer name"
              fullWidth
              required
              value={buyerName}
              onChange={(e) => setBuyerName(e.target.value)}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Buyer contact email"
              fullWidth
              type="email"
              value={buyerContactEmail}
              onChange={(e) => setBuyerContactEmail(e.target.value)}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Due date"
              fullWidth
              type="date"
              InputLabelProps={{ shrink: true }}
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
            />
          </Grid>
          <Grid item xs={12} md={8}>
            {selectedTemplate ? (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ pt: 1 }}>
                {selectedTemplate.description}
                {selectedTemplate.framework === 'cdp'
                  ? ' · Includes C1.1, C6.1, C6.5, C6.7, C8.2, C11.1 question IDs.'
                  : ''}
              </Typography>
            ) : null}
          </Grid>
          <Grid item xs={12}>
            <Stack direction="row" spacing={1}>
              <Button
                variant="contained"
                disabled={importing || !templateId || !buyerName.trim()}
                onClick={() => void handleImport()}
              >
                {importing ? 'Importing…' : 'Import template'}
              </Button>
            </Stack>
          </Grid>
        </Grid>
      </CardContent>
    </Card>
  );
};

export default BuyerQuestionnaireTemplateImport;
