import React, { useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Grid,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

type Plot = {
  plotId?: string;
  name?: string;
  commodity?: string;
  country?: string;
  latitude?: number | null;
  longitude?: number | null;
  areaHectares?: number | null;
  polygon?: Array<[number, number]>;
};

type EudrPlotRegistryPanelProps = {
  plots?: Plot[];
  ddsReference?: string;
  eudrApplicable?: boolean;
  plotRegistry?: {
    plotCount?: number;
    verifiedPlotCount?: number;
    registryComplete?: boolean;
  };
  onSaved?: () => void;
};

const EudrPlotRegistryPanel: React.FC<EudrPlotRegistryPanelProps> = ({
  plots = [],
  ddsReference = '',
  eudrApplicable = false,
  plotRegistry,
  onSaved,
}) => {
  const [draftPlots, setDraftPlots] = useState<Plot[]>(plots.length ? plots : [{ name: 'Plot 1', commodity: 'wood', country: 'IN' }]);
  const [ddsRef, setDdsRef] = useState(ddsReference);
  const [geoJsonDraft, setGeoJsonDraft] = useState('');
  const [fileFeedback, setFileFeedback] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const updatePlot = (index: number, field: keyof Plot, value: string) => {
    setDraftPlots((prev) => prev.map((plot, i) => {
      if (i !== index) return plot;
      if (field === 'latitude' || field === 'longitude' || field === 'areaHectares') {
        return { ...plot, [field]: value === '' ? null : Number(value) };
      }
      return { ...plot, [field]: value };
    }));
  };

  const handleGeoJsonFile = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file) return;
    setFileFeedback(null);
    try {
      const text = await file.text();
      JSON.parse(text);
      setGeoJsonDraft(text);
      setFileFeedback(`Loaded ${file.name} — review below and save to apply to the first plot.`);
    } catch {
      setFileFeedback('Could not read GeoJSON file — ensure it is valid JSON (.geojson or .json).');
    }
  };

  const save = async () => {
    setSaving(true);
    setError(null);
    try {
      let plotsToSave = draftPlots;
      if (geoJsonDraft.trim()) {
        plotsToSave = draftPlots.map((plot, index) => ({
          ...plot,
          plotId: plot.plotId || `plot_${index + 1}`,
          geoJson: geoJsonDraft.trim(),
        }));
      }
      await ApiService.updateEudrPlots({
        plots: plotsToSave,
        eudrDdsReference: ddsRef.trim() || undefined,
        eudrApplicable,
      });
      setGeoJsonDraft('');
      onSaved?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to save EUDR plots');
    } finally {
      setSaving(false);
    }
  };

  if (!eudrApplicable) {
    return (
      <Alert severity="info">
        Enable EUDR in export profile when agri/forest commodities are exported to the EU.
      </Alert>
    );
  }

  return (
    <Stack spacing={2}>
      <Typography variant="h6">EUDR supplier plot registry</Typography>
      {plotRegistry ? (
        <Chip
          label={`${plotRegistry.verifiedPlotCount ?? 0}/${plotRegistry.plotCount ?? 0} plots verified`}
          color={plotRegistry.registryComplete ? 'success' : 'warning'}
        />
      ) : null}
      {error ? <Alert severity="error">{error}</Alert> : null}
      {draftPlots.map((plot, index) => (
        <Card key={plot.plotId || index} variant="outlined">
          <CardContent>
            <Grid container spacing={2}>
              <Grid item xs={12} md={4}>
                <TextField
                  label="Plot name"
                  fullWidth
                  value={plot.name || ''}
                  onChange={(e) => updatePlot(index, 'name', e.target.value)}
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <TextField
                  label="Commodity"
                  fullWidth
                  value={plot.commodity || 'wood'}
                  onChange={(e) => updatePlot(index, 'commodity', e.target.value)}
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <TextField
                  label="Latitude"
                  fullWidth
                  type="number"
                  value={plot.latitude ?? ''}
                  onChange={(e) => updatePlot(index, 'latitude', e.target.value)}
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <TextField
                  label="Longitude"
                  fullWidth
                  type="number"
                  value={plot.longitude ?? ''}
                  onChange={(e) => updatePlot(index, 'longitude', e.target.value)}
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <TextField
                  label="Area (ha)"
                  fullWidth
                  type="number"
                  value={plot.areaHectares ?? ''}
                  onChange={(e) => updatePlot(index, 'areaHectares', e.target.value)}
                />
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      ))}
      <Box>
        <Button size="small" onClick={() => setDraftPlots((prev) => [...prev, { name: `Plot ${prev.length + 1}`, commodity: 'wood', country: 'IN' }])}>
          Add plot
        </Button>
      </Box>
      <TextField
        label="GeoJSON polygon (optional — applies to first plot on save)"
        fullWidth
        multiline
        minRows={3}
        value={geoJsonDraft}
        onChange={(e) => setGeoJsonDraft(e.target.value)}
        helperText="Paste a GeoJSON Polygon or Feature with lat/lng coordinates, or upload a .geojson file."
      />
      <Button variant="outlined" component="label" size="small">
        Upload GeoJSON file
        <input type="file" hidden accept=".geojson,.json,application/geo+json,application/json" onChange={(e) => void handleGeoJsonFile(e)} />
      </Button>
      {fileFeedback ? <Typography variant="body2" color="text.secondary">{fileFeedback}</Typography> : null}
      <TextField
        label="EU DDS reference (TRACES)"
        fullWidth
        value={ddsRef}
        onChange={(e) => setDdsRef(e.target.value)}
        helperText="Required before due diligence statement submission."
      />
      <Button variant="contained" onClick={() => void save()} disabled={saving}>
        Save plot registry
      </Button>
    </Stack>
  );
};

export default EudrPlotRegistryPanel;
