import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

type HubCardProps = {
  period?: string;
};

export const AccountingConnectorReadinessCard: React.FC<HubCardProps> = ({ period = 'annual' }) => {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<Record<string, unknown> | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getComplianceAccountingConnectors({ period });
      setData((res?.data as Record<string, unknown>) || null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load accounting connector readiness');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    void load();
  }, [load]);

  if (loading) return <CircularProgress size={24} />;
  if (error) return <Alert severity="error">{error}</Alert>;
  const connectors = (data?.connectors || []) as Array<{ id?: string; name?: string; syncReady?: boolean; recommendation?: string }>;

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="subtitle1" gutterBottom>Accounting connector readiness</Typography>
        <List dense>
          {connectors.map((entry) => (
            <ListItem key={entry.id} disableGutters>
              <ListItemText primary={entry.name || entry.id} secondary={entry.recommendation} />
              <Chip
                size="small"
                label={entry.syncReady ? 'Sync ready' : 'Setup needed'}
                aria-label={entry.syncReady ? 'Status: Sync ready' : 'Status: Setup needed'}
                color={entry.syncReady ? 'success' : 'default'}
              />
            </ListItem>
          ))}
        </List>
      </CardContent>
    </Card>
  );
};

export const IcmRegistrySnapshotCard: React.FC<HubCardProps> = ({ period = 'annual' }) => {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<Record<string, unknown> | null>(null);

  useEffect(() => {
    void ApiService.getComplianceIcmRegistrySnapshot({ period })
      .then((res) => setData((res?.data as Record<string, unknown>) || null))
      .finally(() => setLoading(false));
  }, [period]);

  if (loading) return <CircularProgress size={24} />;
  const icm = (data?.indianCarbonMarket || {}) as Record<string, unknown>;
  const workflow = (data?.icmWorkflow || {}) as Record<string, unknown>;

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="subtitle1" gutterBottom>ICM registry snapshot</Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          <Chip size="small" label={`Workflow: ${String(workflow.stage || workflow.status || 'not_started')}`} />
          <Chip size="small" label={`Credits tracked: ${String(icm.availableCredits ?? '—')}`} variant="outlined" />
        </Stack>
      </CardContent>
    </Card>
  );
};

export const VendorP2RolloutCard: React.FC<HubCardProps> = ({ period = 'annual' }) => {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<Record<string, unknown> | null>(null);

  useEffect(() => {
    void ApiService.getComplianceVendorP2Rollout({ period })
      .then((res) => setData((res?.data as Record<string, unknown>) || null))
      .finally(() => setLoading(false));
  }, [period]);

  if (loading) return <CircularProgress size={24} />;

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="subtitle1" gutterBottom>Vendor P2 rollout</Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 1 }}>
          <Chip size="small" label={`Phase: ${String(data?.rolloutPhase || 'unknown')}`} />
          <Chip size="small" label={`Shadow mismatches: ${Number(data?.shadowMismatchCount || 0)}`} variant="outlined" />
        </Stack>
        {(data?.recommendations as string[] | undefined)?.slice(0, 2).map((item) => (
          <Typography key={item} variant="body2" color="text.secondary">{item}</Typography>
        ))}
      </CardContent>
    </Card>
  );
};

export const Scope3AssuranceExportPanel: React.FC<{
  scope3Quality?: {
    assuranceGradeReady?: boolean;
    categoryCoverageCount?: number;
    warnings?: string[];
    dataQualityTier?: string;
  } | null;
  cbamTier1Coverage?: {
    tierSummary?: { tier1Count?: number; tier2Count?: number; tier3Count?: number };
    tier1SharePct?: number | null;
    submissionReady?: boolean;
  } | null;
}> = ({ scope3Quality, cbamTier1Coverage }) => (
  <Stack spacing={2}>
    <Card variant="outlined">
      <CardContent>
        <Typography variant="subtitle1" gutterBottom>Scope 3 assurance-grade status</Typography>
        <Chip
          size="small"
          sx={{ mb: 1 }}
          label={scope3Quality?.assuranceGradeReady ? 'Assurance-grade ready' : 'Needs improvement'}
          color={scope3Quality?.assuranceGradeReady ? 'success' : 'warning'}
        />
        <Typography variant="body2" color="text.secondary">
          {scope3Quality?.categoryCoverageCount ?? 0} categories with activity data · tier {scope3Quality?.dataQualityTier || 'incomplete'}
        </Typography>
        {(scope3Quality?.warnings || []).slice(0, 3).map((warning) => (
          <Alert key={warning} severity="warning" sx={{ mt: 1 }}>{warning}</Alert>
        ))}
      </CardContent>
    </Card>
    {cbamTier1Coverage ? (
      <Card variant="outlined">
        <CardContent>
          <Typography variant="subtitle1" gutterBottom>CBAM Tier-1 coverage</Typography>
          <Typography variant="body2">
            Tier 1: {cbamTier1Coverage.tierSummary?.tier1Count ?? 0} ·
            Tier 2: {cbamTier1Coverage.tierSummary?.tier2Count ?? 0} ·
            Tier 3: {cbamTier1Coverage.tierSummary?.tier3Count ?? 0}
          </Typography>
          {cbamTier1Coverage.tier1SharePct != null ? (
            <Typography variant="body2" color="text.secondary">
              Tier-1 share: {cbamTier1Coverage.tier1SharePct}%
            </Typography>
          ) : null}
        </CardContent>
      </Card>
    ) : null}
  </Stack>
);

export const EcovadisAssessmentPanel: React.FC<{
  ecovadis?: Record<string, unknown> | null;
  onSaved?: () => void;
}> = ({ ecovadis, onSaved }) => {
  const [score, setScore] = useState('');
  const [note, setNote] = useState('');
  const [saving, setSaving] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  const importScore = async () => {
    const numeric = Number(score);
    if (!Number.isFinite(numeric)) return;
    setSaving(true);
    setFeedback(null);
    try {
      await ApiService.importEcovadisAssessment({ score: numeric, note: note.trim() || undefined });
      setFeedback('EcoVadis score imported.');
      setScore('');
      setNote('');
      onSaved?.();
    } catch (e) {
      setFeedback(e instanceof Error ? e.message : 'Import failed');
    } finally {
      setSaving(false);
    }
  };

  const history = (ecovadis?.assessmentHistory || []) as Array<{ score?: number; assessedAt?: string; source?: string }>;

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="subtitle1" gutterBottom>EcoVadis assessment history</Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
          Effective score: {String(ecovadis?.effectiveScore ?? ecovadis?.lastScore ?? '—')} ({String(ecovadis?.scoreSource || 'simulated')})
        </Typography>
        <List dense>
          {history.map((entry, index) => (
            <ListItem key={`${entry.assessedAt}-${index}`} disableGutters>
              <ListItemText
                primary={`${entry.score ?? '—'} — ${entry.source || 'import'}`}
                secondary={entry.assessedAt ? new Date(entry.assessedAt).toLocaleDateString() : undefined}
              />
            </ListItem>
          ))}
        </List>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mt: 1 }}>
          <TextField
            label="Score (0–100)"
            type="number"
            size="small"
            value={score}
            onChange={(e) => setScore(e.target.value)}
            sx={{ minWidth: 140 }}
          />
          <TextField
            label="Note"
            size="small"
            value={note}
            onChange={(e) => setNote(e.target.value)}
            sx={{ flex: 1 }}
          />
          <Button variant="contained" disabled={saving} onClick={() => void importScore()}>
            Import score
          </Button>
        </Stack>
        {feedback ? <Alert severity="info" sx={{ mt: 1 }}>{feedback}</Alert> : null}
      </CardContent>
    </Card>
  );
};
