import React, { useEffect, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  CardContent,
  Grid,
  IconButton,
  MenuItem,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import ApiService from '../../services/api';
import { COMPLIANCE_PANEL_STRINGS } from '../../i18n/compliancePanelLocale';

type GasEntry = {
  gas: string;
  gasSpecies: string;
  scope: string;
  massKg: string;
  facility: string;
};

const GAS_OPTIONS = ['CO2', 'CH4', 'N2O', 'HFCs', 'PFCs', 'SF6', 'NF3'];
const SCOPE_OPTIONS = ['scope1', 'scope2', 'scope3'];
const HFC_SPECIES = ['HFC_134a', 'HFC_32', 'HFC_125', 'HFC_143a', 'HFC_152a', 'HFC_227ea'];
const PFC_SPECIES = ['PFC_14', 'PFC_116'];

const emptyEntry = (): GasEntry => ({
  gas: 'CO2',
  gasSpecies: '',
  scope: 'scope1',
  massKg: '',
  facility: '',
});

type MeasuredGasInventoryPanelProps = {
  initialEntries?: Array<Record<string, unknown>>;
  locale?: 'en' | 'hi';
  onSaved?: () => void;
};

const MeasuredGasInventoryPanel: React.FC<MeasuredGasInventoryPanelProps> = ({
  initialEntries = [],
  locale = 'en',
  onSaved,
}) => {
  const strings = COMPLIANCE_PANEL_STRINGS[locale];
  const [entries, setEntries] = useState<GasEntry[]>([emptyEntry()]);
  const [saving, setSaving] = useState(false);
  const [feedback, setFeedback] = useState<{ severity: 'success' | 'error'; message: string } | null>(null);

  useEffect(() => {
    if (initialEntries.length > 0) {
      setEntries(
        initialEntries.map((entry) => ({
          gas: String(entry.gas || 'CO2'),
          gasSpecies: String(entry.gasSpecies || ''),
          scope: String(entry.scope || 'scope1'),
          massKg: entry.massKg != null ? String(entry.massKg) : '',
          facility: String(entry.facility || ''),
        }))
      );
    }
  }, [initialEntries]);

  const updateEntry = (index: number, field: keyof GasEntry, value: string) => {
    setEntries((prev) => prev.map((entry, i) => (i === index ? { ...entry, [field]: value } : entry)));
  };

  const save = async () => {
    setSaving(true);
    setFeedback(null);
    try {
      const payload = entries
        .filter((entry) => Number(entry.massKg) > 0)
        .map((entry) => ({
          gas: entry.gas,
          gasSpecies: entry.gasSpecies.trim() || undefined,
          scope: entry.scope,
          massKg: Number(entry.massKg),
          facility: entry.facility.trim() || undefined,
        }));
      if (payload.length === 0) {
        setFeedback({ severity: 'error', message: strings.measuredGasEmptyError });
        return;
      }
      await ApiService.saveMeasuredGasInventory(payload);
      setFeedback({ severity: 'success', message: strings.measuredGasSaveSuccess });
      onSaved?.();
    } catch (e) {
      setFeedback({ severity: 'error', message: e instanceof Error ? e.message : strings.measuredGasSaveFailed });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="subtitle1" gutterBottom>{strings.measuredGasTitle}</Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          {strings.measuredGasSubtitle}
        </Typography>
        {feedback ? <Alert severity={feedback.severity} sx={{ mb: 2 }}>{feedback.message}</Alert> : null}
        <Stack spacing={2}>
          {entries.map((entry, index) => (
            <Grid container spacing={2} key={`gas-entry-${index}`} alignItems="center">
              <Grid item xs={12} sm={2}>
                <TextField
                  select
                  label="Gas"
                  fullWidth
                  size="small"
                  value={entry.gas}
                  onChange={(e) => {
                    const nextGas = e.target.value;
                    setEntries((prev) => prev.map((row, i) => {
                      if (i !== index) return row;
                      let gasSpecies = row.gasSpecies;
                      if (nextGas !== 'HFCs' && nextGas !== 'PFCs') {
                        gasSpecies = '';
                      } else if (nextGas === 'HFCs' && !gasSpecies) {
                        gasSpecies = 'HFC_134a';
                      } else if (nextGas === 'PFCs' && !gasSpecies) {
                        gasSpecies = 'PFC_14';
                      }
                      return { ...row, gas: nextGas, gasSpecies };
                    }));
                  }}
                >
                  {GAS_OPTIONS.map((gas) => (
                    <MenuItem key={gas} value={gas}>{gas}</MenuItem>
                  ))}
                </TextField>
              </Grid>
              {(entry.gas === 'HFCs' || entry.gas === 'PFCs') && (
                <Grid item xs={12} sm={2}>
                  <TextField
                    select
                    label="Species"
                    fullWidth
                    size="small"
                    value={entry.gasSpecies || (entry.gas === 'HFCs' ? 'HFC_134a' : 'PFC_14')}
                    onChange={(e) => updateEntry(index, 'gasSpecies', e.target.value)}
                  >
                    {(entry.gas === 'HFCs' ? HFC_SPECIES : PFC_SPECIES).map((species) => (
                      <MenuItem key={species} value={species}>{species}</MenuItem>
                    ))}
                  </TextField>
                </Grid>
              )}
              <Grid item xs={12} sm={2}>
                <TextField
                  select
                  label="Scope"
                  fullWidth
                  size="small"
                  value={entry.scope}
                  onChange={(e) => updateEntry(index, 'scope', e.target.value)}
                >
                  {SCOPE_OPTIONS.map((scope) => (
                    <MenuItem key={scope} value={scope}>{scope}</MenuItem>
                  ))}
                </TextField>
              </Grid>
              <Grid item xs={12} sm={2}>
                <TextField
                  label="Mass (kg)"
                  fullWidth
                  size="small"
                  type="number"
                  value={entry.massKg}
                  onChange={(e) => updateEntry(index, 'massKg', e.target.value)}
                />
              </Grid>
              <Grid item xs={10} sm={2}>
                <TextField
                  label="Facility"
                  fullWidth
                  size="small"
                  value={entry.facility}
                  onChange={(e) => updateEntry(index, 'facility', e.target.value)}
                />
              </Grid>
              <Grid item xs={2} sm={1}>
                <IconButton
                  aria-label="Remove gas entry"
                  disabled={entries.length === 1}
                  onClick={() => setEntries((prev) => prev.filter((_, i) => i !== index))}
                >
                  <DeleteOutlineIcon fontSize="small" />
                </IconButton>
              </Grid>
            </Grid>
          ))}
        </Stack>
        <Stack direction="row" spacing={1} sx={{ mt: 2 }}>
          <Button size="small" onClick={() => setEntries((prev) => [...prev, emptyEntry()])}>
            Add gas row
          </Button>
          <Button variant="contained" onClick={() => void save()} disabled={saving}>
            {strings.measuredGasSaveButton}
          </Button>
        </Stack>
      </CardContent>
    </Card>
  );
};

export default MeasuredGasInventoryPanel;
