import React from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  LinearProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';
import BuyerPackQuestionnaireWizard, { type SupplierQuestionnaireRecord } from './BuyerPackQuestionnaireWizard';
import ApiService from '../../services/api';

export type BuyerQuestionnaireDetail = {
  id?: string | null;
  buyerName: string;
  buyerContactEmail?: string | null;
  framework: string;
  frameworkLabel: string;
  status: string;
  dueDate?: string | null;
  daysToDue?: number | null;
  urgency?: string;
  readinessScore: number;
  packReady?: boolean;
  missingPackFields?: string[];
  missingQuestionnaireFields?: string[];
  missingQuestionFields?: Array<{
    responseKey?: string;
    questionRef?: string | null;
    label?: string;
    displayRef?: string;
  }>;
  evidenceDocumentCount?: number;
  packHubLink?: string;
  packValidation?: {
    valid?: boolean;
    missingFields?: string[];
    warnings?: string[];
  } | null;
  portalValidation?: {
    valid?: boolean;
    portalScore?: number;
    portalReady?: boolean;
    errors?: string[];
    warnings?: string[];
    crossCheckMismatches?: Array<{ field?: string; message?: string }>;
  } | null;
};

export type BuyerPackReadiness = {
  readinessScore?: number | null;
  threshold?: number;
  openQuestionnaireCount?: number;
  totalQuestionnaireCount?: number;
  overdueCount?: number;
  packExportReady?: boolean;
  questionnaires?: BuyerQuestionnaireDetail[];
};

type BuyerQuestionnaireGapPanelProps = {
  buyerPackReadiness?: BuyerPackReadiness | null;
  supplierQuestionnaires?: SupplierQuestionnaireRecord[];
  period?: string;
  onRefresh?: () => void;
};

const urgencyColor = (urgency?: string): 'error' | 'warning' | 'default' | 'success' => {
  if (urgency === 'overdue') return 'error';
  if (urgency === 'high') return 'error';
  if (urgency === 'medium') return 'warning';
  return 'default';
};

const humanizeField = (field: string): string =>
  field
    .split('.')
    .pop()
    ?.replace(/([A-Z])/g, ' $1')
    .replace(/_/g, ' ')
    .replace(/^./, (c) => c.toUpperCase())
    .trim() || field;

const questionnaireFieldLabel: Record<string, string> = {
  dueDate: 'Due date not set',
  overdue: 'Response overdue',
  buyerContactEmail: 'Buyer contact email missing',
  evidenceDocuments: 'No evidence documents linked',
  status: 'Still in draft — mark as sent when submitted',
  responses: 'Questionnaire responses not started',
  framework_pack_mapping: 'Map to a disclosure pack (CDP, CSRD, etc.)'
};

const BuyerQuestionnaireGapPanel: React.FC<BuyerQuestionnaireGapPanelProps> = ({
  buyerPackReadiness,
  supplierQuestionnaires = [],
  period = 'annual',
  onRefresh,
}) => {
  const questionnaires = buyerPackReadiness?.questionnaires || [];
  const openQuestionnaires = questionnaires.filter(
    (q) => q.status !== 'accepted' && q.status !== 'responded'
  );

  const resolveQuestionnaireRecord = (detail: BuyerQuestionnaireDetail): SupplierQuestionnaireRecord | null => {
    const match = supplierQuestionnaires.find(
      (entry) => String(entry.id || entry._id) === String(detail.id)
        || (entry.buyerName === detail.buyerName && entry.framework === detail.framework)
    );
    return match || null;
  };

  const handlePrefill = async (questionnaireId?: string | null) => {
    if (!questionnaireId) return;
    try {
      await ApiService.prefillSupplierQuestionnaireFromInventory(questionnaireId, { period });
      onRefresh?.();
    } catch {
      // Parent surfaces load errors; keep gap panel lightweight
    }
  };

  if (!questionnaires.length) {
    return (
      <Alert severity="info">
        No buyer questionnaires registered yet. Add requests when customers send CDP, CSRD, EcoVadis,
        or BRSR audit templates.
      </Alert>
    );
  }

  return (
    <Stack spacing={2}>
      {buyerPackReadiness?.readinessScore != null ? (
        <Card variant="outlined">
          <CardContent>
            <Stack direction="row" spacing={2} alignItems="center" flexWrap="wrap" sx={{ mb: 1 }}>
              <Typography variant="h5" fontWeight={700}>
                {Math.round(buyerPackReadiness.readinessScore)}%
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Buyer portal readiness
                {buyerPackReadiness.openQuestionnaireCount
                  ? ` · ${buyerPackReadiness.openQuestionnaireCount} open request(s)`
                  : ''}
                {buyerPackReadiness.overdueCount
                  ? ` · ${buyerPackReadiness.overdueCount} overdue`
                  : ''}
              </Typography>
            </Stack>
            <LinearProgress
              variant="determinate"
              value={Math.min(100, Math.max(0, buyerPackReadiness.readinessScore))}
              sx={{ height: 8, borderRadius: 4 }}
            />
            {buyerPackReadiness.threshold != null ? (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
                Target: {buyerPackReadiness.threshold}% before buyer submission
              </Typography>
            ) : null}
          </CardContent>
        </Card>
      ) : null}

      {openQuestionnaires.map((q) => {
        const packGaps = (q.missingPackFields || []).slice(0, 5);
        const questionFieldGaps = (q.missingQuestionFields || []).slice(0, 6);
        const metaGaps = (q.missingQuestionnaireFields || [])
          .filter((field) => !field.includes(' — '))
          .map((field) => questionnaireFieldLabel[field] || humanizeField(field));
        const warnings = (q.packValidation?.warnings || []).slice(0, 2);

        return (
          <Card key={q.id || q.buyerName} variant="outlined">
            <CardContent>
              <Stack direction="row" justifyContent="space-between" alignItems="flex-start" flexWrap="wrap" gap={1}>
                <Box>
                  <Typography variant="subtitle1" fontWeight={700}>
                    {q.buyerName}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {q.frameworkLabel} · {q.status.replace(/_/g, ' ')}
                  </Typography>
                </Box>
                <Stack direction="row" spacing={1} flexWrap="wrap">
                  <Chip size="small" label={`${q.readinessScore}% ready`} />
                  <Chip
                    size="small"
                    label={q.urgency === 'overdue' ? 'Overdue' : q.urgency || 'normal'}
                    color={urgencyColor(q.urgency)}
                  />
                  {q.packReady ? (
                    <Chip size="small" color="success" label="Pack valid" />
                  ) : (
                    <Chip size="small" color="warning" label="Pack gaps" />
                  )}
                </Stack>
              </Stack>

              {q.daysToDue != null ? (
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                  {q.daysToDue < 0
                    ? `${Math.abs(q.daysToDue)} day(s) overdue`
                    : `Due in ${q.daysToDue} day(s)`}
                  {q.dueDate ? ` (${new Date(q.dueDate).toLocaleDateString()})` : ''}
                </Typography>
              ) : null}

              {(metaGaps.length > 0 || questionFieldGaps.length > 0 || packGaps.length > 0 || warnings.length > 0) ? (
                <Box sx={{ mt: 2 }}>
                  <Typography variant="subtitle2" gutterBottom>
                    Missing details
                  </Typography>
                  <Stack spacing={0.75}>
                    {questionFieldGaps.map((field) => (
                      <Typography key={field.responseKey || field.displayRef} variant="body2" color="text.secondary">
                        • {field.displayRef || field.label}
                        {field.questionRef ? (
                          <Chip
                            size="small"
                            label={field.questionRef}
                            variant="outlined"
                            sx={{ ml: 1, verticalAlign: 'middle' }}
                          />
                        ) : null}
                      </Typography>
                    ))}
                    {metaGaps.map((label) => (
                      <Typography key={label} variant="body2" color="text.secondary">
                        • {label}
                      </Typography>
                    ))}
                    {packGaps.map((field) => (
                      <Typography key={field} variant="body2" color="text.secondary">
                        • Pack field: {humanizeField(field)}
                      </Typography>
                    ))}
                    {warnings.map((warning) => (
                      <Typography key={warning} variant="body2" color="warning.main">
                        • {warning}
                      </Typography>
                    ))}
                  </Stack>
                </Box>
              ) : (
                <Alert severity="success" sx={{ mt: 2 }}>
                  All required pack fields and questionnaire metadata are complete for this buyer.
                </Alert>
              )}

              <Stack direction="row" spacing={1} sx={{ mt: 2 }} flexWrap="wrap">
                {q.packHubLink ? (
                  <Button size="small" component={RouterLink} to={q.packHubLink}>
                    Complete {q.frameworkLabel.split(' ')[0]} pack
                  </Button>
                ) : null}
                {q.id ? (
                  <Button size="small" variant="outlined" onClick={() => void handlePrefill(q.id)}>
                    Prefill from inventory
                  </Button>
                ) : null}
                <Button size="small" component={RouterLink} to={DOCUMENT_UPLOAD_PATH}>
                  Attach evidence
                </Button>
              </Stack>

              {resolveQuestionnaireRecord(q) ? (
                <Box sx={{ mt: 2 }}>
                  <BuyerPackQuestionnaireWizard
                    questionnaire={resolveQuestionnaireRecord(q) as SupplierQuestionnaireRecord}
                    period={period}
                    onSaved={onRefresh}
                  />
                </Box>
              ) : null}
            </CardContent>
          </Card>
        );
      })}

      {openQuestionnaires.length === 0 && questionnaires.length > 0 ? (
        <Alert severity="success">
          All registered buyer questionnaires are marked responded or accepted.
        </Alert>
      ) : null}

      {questionnaires.length > 0 ? (
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Buyer</TableCell>
              <TableCell>Framework</TableCell>
              <TableCell>Status</TableCell>
              <TableCell align="right">Score</TableCell>
              <TableCell align="right">Evidence</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {questionnaires.map((q) => (
              <TableRow key={q.id || `${q.buyerName}-${q.framework}`}>
                <TableCell>{q.buyerName}</TableCell>
                <TableCell>{q.frameworkLabel}</TableCell>
                <TableCell>{q.status.replace(/_/g, ' ')}</TableCell>
                <TableCell align="right">{q.readinessScore}%</TableCell>
                <TableCell align="right">{q.evidenceDocumentCount ?? 0}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      ) : null}
    </Stack>
  );
};

export default BuyerQuestionnaireGapPanel;
