import React, { useState } from 'react';
import {
  Alert,
  Button,
  Card,
  CardContent,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

type Entity = {
  entityId?: string;
  legalName?: string;
  country?: string;
  ownershipPercent?: number;
  scope1Kg?: number;
  scope2Kg?: number;
  scope3Kg?: number;
};

type GroupBoundaryPanelProps = {
  groupBoundary?: {
    parentEntity?: string | null;
    approach?: string;
    entities?: Entity[];
    rolledUpEmissionsKg?: { scope1?: number; scope2?: number; scope3?: number; total?: number };
    boundaryReady?: boolean;
    gaps?: string[];
  };
  onSaved?: () => void;
};

const GroupBoundaryPanel: React.FC<GroupBoundaryPanelProps> = ({ groupBoundary, onSaved }) => {
  const [parentLegalName, setParentLegalName] = useState(groupBoundary?.parentEntity || '');
  const [approach, setApproach] = useState(groupBoundary?.approach || 'operational_control');
  const [entities, setEntities] = useState<Entity[]>(
    groupBoundary?.entities?.length
      ? groupBoundary.entities
      : [{ legalName: 'Primary entity', country: 'IN', ownershipPercent: 100 }]
  );
  const [saving, setSaving] = useState(false);

  const updateEntity = (index: number, field: keyof Entity, value: string) => {
    setEntities((prev) => prev.map((entity, i) => {
      if (i !== index) return entity;
      if (['ownershipPercent', 'scope1Kg', 'scope2Kg', 'scope3Kg'].includes(field)) {
        return { ...entity, [field]: value === '' ? 0 : Number(value) };
      }
      return { ...entity, [field]: value };
    }));
  };

  const save = async () => {
    setSaving(true);
    try {
      await ApiService.updateGroupBoundary({
        parentLegalName,
        consolidationApproach: approach,
        entities,
      });
      onSaved?.();
    } finally {
      setSaving(false);
    }
  };

  return (
    <Stack spacing={2}>
      <Typography variant="h6">Multi-entity group boundary</Typography>
      {(groupBoundary?.gaps || []).map((gap) => (
        <Alert key={gap} severity="warning">{gap}</Alert>
      ))}
      {groupBoundary?.rolledUpEmissionsKg ? (
        <Alert severity="info">
          Rolled-up emissions (kg CO2e): Scope 1 {groupBoundary.rolledUpEmissionsKg.scope1?.toLocaleString()} ·
          Scope 2 {groupBoundary.rolledUpEmissionsKg.scope2?.toLocaleString()} ·
          Scope 3 {groupBoundary.rolledUpEmissionsKg.scope3?.toLocaleString()}
        </Alert>
      ) : null}
      <TextField
        label="Parent legal name"
        fullWidth
        value={parentLegalName}
        onChange={(e) => setParentLegalName(e.target.value)}
      />
      <FormControl fullWidth>
        <InputLabel>Consolidation approach</InputLabel>
        <Select
          label="Consolidation approach"
          value={approach}
          onChange={(e) => setApproach(String(e.target.value))}
        >
          <MenuItem value="operational_control">Operational control</MenuItem>
          <MenuItem value="equity_share">Equity share</MenuItem>
          <MenuItem value="financial_control">Financial control</MenuItem>
        </Select>
      </FormControl>
      {entities.map((entity, index) => (
        <Card key={entity.entityId || index} variant="outlined">
          <CardContent>
            <Grid container spacing={2}>
              <Grid item xs={12} md={4}>
                <TextField
                  label="Legal name"
                  fullWidth
                  value={entity.legalName || ''}
                  onChange={(e) => updateEntity(index, 'legalName', e.target.value)}
                />
              </Grid>
              <Grid item xs={6} md={2}>
                <TextField
                  label="Country"
                  fullWidth
                  value={entity.country || 'IN'}
                  onChange={(e) => updateEntity(index, 'country', e.target.value)}
                />
              </Grid>
              <Grid item xs={6} md={2}>
                <TextField
                  label="Ownership %"
                  fullWidth
                  type="number"
                  value={entity.ownershipPercent ?? 100}
                  onChange={(e) => updateEntity(index, 'ownershipPercent', e.target.value)}
                />
              </Grid>
              <Grid item xs={4} md={1.3}>
                <TextField
                  label="Scope 1 kg"
                  fullWidth
                  type="number"
                  value={entity.scope1Kg ?? ''}
                  onChange={(e) => updateEntity(index, 'scope1Kg', e.target.value)}
                />
              </Grid>
              <Grid item xs={4} md={1.3}>
                <TextField
                  label="Scope 2 kg"
                  fullWidth
                  type="number"
                  value={entity.scope2Kg ?? ''}
                  onChange={(e) => updateEntity(index, 'scope2Kg', e.target.value)}
                />
              </Grid>
              <Grid item xs={4} md={1.3}>
                <TextField
                  label="Scope 3 kg"
                  fullWidth
                  type="number"
                  value={entity.scope3Kg ?? ''}
                  onChange={(e) => updateEntity(index, 'scope3Kg', e.target.value)}
                />
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      ))}
      <Button size="small" onClick={() => setEntities((prev) => [...prev, { legalName: `Entity ${prev.length + 1}`, country: 'IN', ownershipPercent: 100 }])}>
        Add entity
      </Button>
      <Button variant="contained" onClick={() => void save()} disabled={saving}>
        Save group boundary
      </Button>
    </Stack>
  );
};

export default GroupBoundaryPanel;
