import React from 'react';
import {
  Alert,
  Button,
  Chip,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';

type Connector = {
  id?: string;
  label?: string;
  connected?: boolean;
  liveSync?: boolean;
  status?: string;
};

type HrErpConnectorPanelProps = {
  hrErpReadiness?: {
    connectors?: Connector[];
    liveConnectorCount?: number;
    syncReady?: boolean;
    blockers?: string[];
    recommendedConnector?: string;
  };
  onSync?: () => void;
  syncing?: boolean;
};

const HrErpConnectorPanel: React.FC<HrErpConnectorPanelProps> = ({
  hrErpReadiness,
  onSync,
  syncing = false,
}) => {
  const connectors = hrErpReadiness?.connectors || [];

  return (
    <Stack spacing={2}>
      <Typography variant="h6">HR / ERP connector readiness</Typography>
      <Chip
        label={hrErpReadiness?.syncReady ? 'S/G sync ready' : 'Connectors needed'}
        color={hrErpReadiness?.syncReady ? 'success' : 'warning'}
      />
      {(hrErpReadiness?.blockers || []).map((blocker) => (
        <Alert key={blocker} severity="warning">{blocker}</Alert>
      ))}
      <List dense>
        {connectors.map((connector) => (
          <ListItem key={connector.id} disableGutters>
            <ListItemText primary={connector.label || connector.id} secondary={connector.status} />
            <Chip
              size="small"
              label={connector.connected ? 'Connected' : 'Available'}
              color={connector.connected ? 'success' : 'default'}
              variant="outlined"
            />
          </ListItem>
        ))}
      </List>
      <Stack direction="row" spacing={1} flexWrap="wrap">
        <Button component={RouterLink} to="/data?section=connectors" variant="outlined" size="small">
          Manage connectors
        </Button>
        {onSync ? (
          <Button variant="contained" size="small" onClick={onSync} disabled={syncing}>
            {syncing ? 'Syncing…' : 'Sync BRSR S/G from HR/ERP'}
          </Button>
        ) : null}
      </Stack>
      {hrErpReadiness?.recommendedConnector ? (
        <Typography variant="caption" color="text.secondary">
          Recommended: {hrErpReadiness.recommendedConnector}
        </Typography>
      ) : null}
    </Stack>
  );
};

export default HrErpConnectorPanel;
